function CategoryGrid({ items, locale }: { items: Category[]; locale: Locale }) {
  return <div className="category-grid">{items.map((category) => { const Icon = categoryIcons[category.icon] ?? Wrench; return <Link className="category-card" href={`/search?category=${encodeURIComponent(category.subcategories[0])}`} key={category.id}><span className="category-icon"><Icon size={20} /></span><span><h3>{translateText(locale, category.name)}</h3><p>{translateText(locale, category.description)}</p><span className="category-count">{category.count} {translateText(locale, "illustrative demo profiles")} <ArrowRight size={12} /></span></span></Link> })}</div>
}

function WorkerCard({ worker, isSaved, onToggleSave, locale }: { worker: Worker; isSaved: boolean; onToggleSave: (id: string) => void; locale: Locale }) {
  return <article className="worker-card"><Link href={`/workers/${worker.id}`}><div className="worker-card-head"><WorkerAvatar initials={worker.initials} /><div className="worker-card-title"><h3>{worker.name}</h3><p>{worker.headline}</p></div></div></Link><button aria-label={`${isSaved ? "Unsave" : "Save"} ${worker.name}`} aria-pressed={isSaved} className={`save-button ${isSaved ? "is-saved" : ""}`} onClick={() => onToggleSave(worker.id)} type="button"><Heart fill={isSaved ? "currentColor" : "none"} size={16} /></button><div className="worker-card-badges">{worker.verified && <span className="status-pill"><BadgeCheck size={12} /> {t(locale, "verified")}</span>}{worker.available && <span className="status-pill gold"><span className="eyebrow-dot" /> {t(locale, "available")}</span>}</div><div className="worker-card-location"><MapPin size={13} />{worker.location}</div><div className="worker-card-bottom"><span className="rating"><Star size={13} />{worker.rating}<span>({worker.reviewCount})</span></span><span className="price">{formatETB(worker.hourlyRate, locale)} <small>{t(locale, "perHour")}</small></span></div></article>
}

export function WorkerGrid({ items, savedIds, onToggleSave, locale }: { items: Worker[]; savedIds: string[]; onToggleSave: (id: string) => void; locale: Locale }) {
  return <div className="worker-grid">{items.map((worker) => <WorkerCard key={worker.id} worker={worker} isSaved={savedIds.includes(worker.id)} onToggleSave={onToggleSave} locale={locale} />)}</div>
}

function JobList({ jobs: items, onApply, appliedIds = [] }: { jobs: Job[]; onApply?: (job: Job) => void; appliedIds?: string[] }) {
  return <div className="job-list">{items.map((job) => <article className="job-card" key={job.id}><div aria-hidden="true" className="job-logo">{job.company.charAt(0)}</div><div className="job-main"><Link href={`/jobs/${job.id}`}><h3>{job.title}</h3></Link><div className="job-meta"><span><BriefcaseBusiness size={12} />{job.company}</span><span><MapPin size={12} />{job.location}</span><span><Clock3 size={12} />{job.posted}</span></div></div><div className="job-aside"><span className="job-tag">{job.type}</span><strong className="price">{job.salary}</strong>{onApply && <button aria-pressed={appliedIds.includes(job.id)} className="button button-outline button-small" disabled={appliedIds.includes(job.id)} onClick={() => onApply(job)} type="button">{appliedIds.includes(job.id) ? "Applied" : "Apply"}</button>}</div></article>)}</div>
}

export function CategoriesPage({ locale }: { locale: Locale }) {
  const [query, setQuery] = useState("")
  const filtered = categories.map((category) => ({ ...category, subcategories: category.subcategories.filter((item) => !query || item.toLowerCase().includes(query.toLowerCase())) })).filter((category) => !query || category.name.toLowerCase().includes(query.toLowerCase()) || category.subcategories.length > 0)
  return <main className="page-wrap"><div className="page-content"><PageIntro eyebrow={translateText(locale, "Find your people")} title={translateText(locale, "Every skill has a place.")} description={translateText(locale, "Explore local services and skilled professionals across Adama. New categories can grow right alongside the community.")} /><form className="search-box search-box-compact category-search" onSubmit={(event) => event.preventDefault()}><Search className="search-box-icon" size={18} /><label className="sr-only" htmlFor="category-search">{translateText(locale, "Search categories")}</label><input id="category-search" onChange={(event) => setQuery(event.target.value)} placeholder={translateText(locale, "Search services or skills")} value={query} /></form><div className="category-page-list">{filtered.map((category) => <section className="category-block" key={category.id}><div className="category-block-heading"><span className="category-icon"><CategoryIcon category={category} /></span><div><h2>{translateText(locale, category.name)}</h2><p>{translateText(locale, category.description)}</p></div><span className="category-count">{category.count} {translateText(locale, "illustrative demo profiles")}</span></div><div className="subcategory-list">{category.subcategories.map((item) => <Link href={`/search?category=${encodeURIComponent(item)}`} key={item}>{item}<ArrowRight size={13} /></Link>)}</div></section>)}{filtered.length === 0 && <div className="empty-state"><div className="empty-state-icon"><Search size={20} /></div><h2>{translateText(locale, "No categories found")}</h2><p>{translateText(locale, "Try a different skill or clear your search.")}</p><button className="button button-outline button-small" onClick={() => setQuery("")} type="button">{translateText(locale, "Clear search")}</button></div>}</div><div className="category-page-note"><ShieldCheck size={20} /><div><strong>{translateText(locale, "Built to grow with Ethiopia")}</strong><p>{translateText(locale, "Service categories are organized to make it easy for new skills and local trades to find their place.")}</p></div></div></div></main>
}

function CategoryIcon({ category }: { category: Category }) { const Icon = categoryIcons[category.icon] ?? Wrench; return <Icon size={19} /> }

export function SearchPage({ locale, savedIds, onToggleSave }: { locale: Locale; savedIds: string[]; onToggleSave: (id: string) => void }) {
  const searchParams = useSearchParams()
  const router = useRouter()
  const queryParam = searchParams.get("q") ?? ""
  const categoryParam = searchParams.get("category") ?? ""
  const locationParam = searchParams.get("location") ?? ""
  const searchString = searchParams.toString()
  const paramsKey = JSON.stringify(["q", "category", "location", "radius", "price", "experience", "language", "rating", "verified", "available", "sort", "view"].map((key) => searchParams.get(key)))
  const urlParamsRef = useRef(new URLSearchParams(searchString))
  useEffect(() => { urlParamsRef.current = new URLSearchParams(searchString) }, [searchString])
  const [query, setQuery] = useState(queryParam)
  const [category, setCategory] = useState(categoryParam)
  const [location, setLocation] = useState(locationParam)
  const [availableOnly, setAvailableOnly] = useState(false)
  const [verifiedOnly, setVerifiedOnly] = useState(false)
  const [minRating, setMinRating] = useState(0)
  const [maxPrice, setMaxPrice] = useState("")
  const [minExperience, setMinExperience] = useState("")
  const [language, setLanguage] = useState("")
  const [radiusKm, setRadiusKm] = useState("20")
  const [sortBy, setSortBy] = useState<"relevance" | "rating" | "price-low" | "price-high" | "newest">("relevance")
  const [display, setDisplay] = useState<"grid" | "list">("grid")
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [recentSearches, setRecentSearches] = useDemoStorageState<string[]>("carava-demo-recent-searches", [])
  const filterKey = JSON.stringify([query, category, location, availableOnly, verifiedOnly, minRating, maxPrice, minExperience, language, radiusKm, sortBy])
  const [pageState, setPageState] = useState({ filterKey: "", page: 1 })
  const currentPage = pageState.filterKey === filterKey ? pageState.page : 1
  const setCurrentPage = (nextPage: number | ((currentPage: number) => number)) => setPageState((current) => {
    const page = current.filterKey === filterKey ? current.page : 1
    return { filterKey, page: typeof nextPage === "function" ? nextPage(page) : nextPage }
  })
  const [syncedParamsKey, setSyncedParamsKey] = useState(paramsKey)
  if (syncedParamsKey !== paramsKey) {
    setSyncedParamsKey(paramsKey)
    setQuery(queryParam)
    setCategory(categoryParam)
    setLocation(locationParam)
    const radius = searchParams.get("radius") ?? "20"
    setRadiusKm(["5", "10", "20", "40"].includes(radius) ? radius : "20")
    setMaxPrice(searchParams.get("price") ?? "")
    setMinExperience(searchParams.get("experience") ?? "")
    setLanguage(searchParams.get("language") ?? "")
    setMinRating(Number(searchParams.get("rating") ?? 0) || 0)
    setVerifiedOnly(searchParams.get("verified") === "1")
    setAvailableOnly(searchParams.get("available") === "1")
    const sort = searchParams.get("sort") ?? "relevance"
    setSortBy(["relevance", "rating", "price-low", "price-high", "newest"].includes(sort) ? sort as typeof sortBy : "relevance")
    setDisplay(searchParams.get("view") === "list" ? "list" : "grid")
    setPageState({ filterKey: "", page: 1 })
  }
  const filters = useMemo(() => ({ query, category, location, availableOnly, verifiedOnly, minRating, maxPrice: maxPrice ? Number(maxPrice) : undefined, minExperience: minExperience ? Number(minExperience) : undefined, language: language || undefined, radiusKm: Number(radiusKm), sortBy, page: currentPage, pageSize: 4 }), [query, category, location, availableOnly, verifiedOnly, minRating, maxPrice, minExperience, language, radiusKm, sortBy, currentPage])
  const { data, error, isLoading, mutate } = useSWR(["carava-worker-search", filters], () => marketplaceApi.searchWorkers(filters), { keepPreviousData: true })
  const filtered = data?.items ?? []
  const total = data?.total ?? 0
  const totalPages = Math.max(1, Math.ceil(total / (data?.pageSize ?? 4)))
  const resetFilters = () => {
    setQuery(""); setCategory(""); setLocation(""); setAvailableOnly(false); setVerifiedOnly(false); setMinRating(0); setMaxPrice(""); setMinExperience(""); setLanguage(""); setRadiusKm("20"); setSortBy("relevance"); setDisplay("grid"); setCurrentPage(1)
    urlParamsRef.current = new URLSearchParams()
    router.replace("/search", { scroll: false })
  }
  const submitSearch = (nextQuery: string, nextLocation?: string) => {
    const normalized = nextQuery.trim()
    const normalizedLocation = (nextLocation ?? "").trim()
    setQuery(normalized)
    setLocation(normalizedLocation)
    setCurrentPage(1)
    if (normalized) {
      const nextRecent = [normalized, ...recentSearches.filter((item) => item.toLowerCase() !== normalized.toLowerCase())].slice(0, 4)
      setRecentSearches(nextRecent)
    }
    const params = new URLSearchParams(urlParamsRef.current)
    if (normalized) params.set("q", normalized); else params.delete("q")
    if (normalizedLocation) params.set("location", normalizedLocation); else params.delete("location")
    urlParamsRef.current = params
    router.replace(`/search${params.size ? `?${params.toString()}` : ""}`, { scroll: false })
  }
  const updateUrlFilters = (next: Record<string, string | number | boolean | undefined>) => {
    const params = new URLSearchParams(urlParamsRef.current)
    Object.entries(next).forEach(([key, value]) => {
      if (value === undefined || value === "" || value === false || value === 0) params.delete(key)
      else params.set(key, String(value))
    })
    urlParamsRef.current = params
    router.replace(`/search${params.size ? `?${params.toString()}` : ""}`, { scroll: false })
  }
  const updateFilter = <T extends string | number | boolean,>(apply: (value: T) => void, key: string, value: T, urlValue?: string | number | boolean) => {
    apply(value)
    setCurrentPage(1)
    updateUrlFilters({ [key]: urlValue ?? value })
  }
  const filterContent = <><div className="filter-group"><h3>{translateText(locale, "Category")}</h3><label className="field"><span className="sr-only">{translateText(locale, "Choose a category")}</span><select onChange={(event) => updateFilter(setCategory, "category", event.target.value)} value={category}><option value="">{translateText(locale, "All skills")}</option>{categories.flatMap((item) => item.subcategories).map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div><div className="filter-group"><h3>{translateText(locale, "Neighborhood")}</h3><label className="field"><span className="sr-only">{translateText(locale, "Choose a neighborhood")}</span><select onChange={(event) => updateFilter(setLocation, "location", event.target.value)} value={location}><option value="">{translateText(locale, "Anywhere in Adama")}</option>{neighborhoods.map((item) => <option key={item} value={item}>{item}</option>)}</select></label><label className="field"><span className="sr-only">{translateText(locale, "Distance radius")}</span><select aria-label={translateText(locale, "Distance radius")} onChange={(event) => updateFilter(setRadiusKm, "radius", event.target.value, event.target.value === "20" ? "" : event.target.value)} value={radiusKm}>{([[5, "Within 5 km"], [10, "Within 10 km"], [20, "Within 20 km"], [40, "Within 40 km"]] as const).map(([km, label]) => <option key={km} value={km}>{translateText(locale, label)}</option>)}</select></label></div><div className="filter-group"><h3>{translateText(locale, "Budget & experience")}</h3><label className="field"><span className="sr-only">{translateText(locale, "Maximum hourly rate in ETB")}</span><select onChange={(event) => updateFilter(setMaxPrice, "price", event.target.value)} value={maxPrice}><option value="">{translateText(locale, "Any hourly price")}</option>{([[300, "Up to ETB 300"], [500, "Up to ETB 500"], [800, "Up to ETB 800"], [1200, "Up to ETB 1,200"]] as const).map(([price, label]) => <option key={price} value={price}>{translateText(locale, label)}</option>)}</select></label><label className="field"><span className="sr-only">{translateText(locale, "Minimum years of experience")}</span><select onChange={(event) => updateFilter(setMinExperience, "experience", event.target.value)} value={minExperience}><option value="">{translateText(locale, "Any experience")}</option>{([[2, "2+ years"], [5, "5+ years"], [10, "10+ years"]] as const).map(([years, label]) => <option key={years} value={years}>{translateText(locale, label)}</option>)}</select></label></div><div className="filter-group"><h3>{translateText(locale, "Language")}</h3><label className="field"><span className="sr-only">{translateText(locale, "Language spoken")}</span><select onChange={(event) => updateFilter(setLanguage, "language", event.target.value)} value={language}><option value="">{translateText(locale, "Any language")}</option><option>{translateText(locale, "Amharic")}</option><option>{translateText(locale, "Afaan Oromo")}</option><option>{translateText(locale, "English")}</option></select></label></div><div className="filter-group"><h3>{translateText(locale, "Trust & availability")}</h3><label className="filter-option"><input checked={verifiedOnly} onChange={(event) => updateFilter(setVerifiedOnly, "verified", event.target.checked, event.target.checked ? "1" : "")} type="checkbox" /> {translateText(locale, "Verified profile")}</label><label className="filter-option"><input checked={availableOnly} onChange={(event) => updateFilter(setAvailableOnly, "available", event.target.checked, event.target.checked ? "1" : "")} type="checkbox" /> {translateText(locale, "Available now")}</label></div><div className="filter-group"><h3>{translateText(locale, "Minimum rating")}</h3><label className="field"><span className="sr-only">{translateText(locale, "Minimum rating")}</span><select onChange={(event) => updateFilter(setMinRating, "rating", Number(event.target.value), Number(event.target.value) || "")} value={minRating}><option value="0">{translateText(locale, "Any rating")}</option><option value="4">{translateText(locale, "4+ stars")}</option><option value="4.5">{translateText(locale, "4.5+ stars")}</option></select></label></div><button className="button button-quiet button-small" onClick={resetFilters} type="button">{translateText(locale, "Clear all filters")}</button></>
  const clearActiveFilter = (key: string) => {
    if (key === "q") updateFilter(setQuery, "q", "")
    else if (key === "category") updateFilter(setCategory, "category", "")
    else if (key === "location") updateFilter(setLocation, "location", "")
    else if (key === "radius") updateFilter(setRadiusKm, "radius", "20", "")
    else if (key === "rating") updateFilter(setMinRating, "rating", 0, "")
    else if (key === "price") updateFilter(setMaxPrice, "price", "")
    else if (key === "experience") updateFilter(setMinExperience, "experience", "")
    else if (key === "language") updateFilter(setLanguage, "language", "")
    else if (key === "verified") updateFilter(setVerifiedOnly, "verified", false, "")
    else if (key === "available") updateFilter(setAvailableOnly, "available", false, "")
  }
  const activeFilters = [
    query && { key: "q", label: `“${query}”` },
    category && { key: "category", label: category },
    location && { key: "location", label: location },
    radiusKm !== "20" && { key: "radius", label: `Within ${radiusKm} km` },
    minRating > 0 && { key: "rating", label: `${minRating}+ stars` },
    maxPrice && { key: "price", label: `Up to ETB ${maxPrice}` },
    minExperience && { key: "experience", label: `${minExperience}+ years` },
    language && { key: "language", label: language },
    verifiedOnly && { key: "verified", label: "Verified" },
    availableOnly && { key: "available", label: "Available now" },
  ].filter(Boolean) as { key: string; label: string }[]
  return <main className="page-wrap"><div className="page-content"><PageIntro eyebrow={translateText(locale, "Find trusted local help")} title={translateText(locale, "People who make things happen.")} description={translateText(locale, "Explore Adama's skilled professionals. Compare experience, reviews, and availability to find the right fit.")} /><div className="search-results-search"><SearchBox key={`${query}-${location}`} compact initialValue={query} initialLocation={location} locale={locale} onSubmit={submitSearch} /></div>{recentSearches.length > 0 && <div className="recent-searches"><span>{translateText(locale, "Recent searches")}</span>{recentSearches.map((item) => <button className="toolbar-chip" key={item} onClick={() => submitSearch(item)} type="button">{item}</button>)}</div>}<div className="search-suggestions"><span>{translateText(locale, "Popular searches")}</span>{["Electrician", "Home cleaning", "Tailor", "Delivery"].map((item) => <button key={item} onClick={() => submitSearch(item)} type="button">{translateText(locale, item)}</button>)}</div><div className="filter-layout"><aside aria-label={translateText(locale, "Worker filters")} className={filtersOpen ? "filter-panel mobile-filters-open" : "filter-panel"}><h2><SlidersHorizontal size={16} /> {translateText(locale, "Refine your search")}</h2>{filterContent}</aside><section aria-label={translateText(locale, "Worker search results")}><div className="search-results-toolbar"><div><strong>{total} {translateText(locale, "professionals")}</strong><span className="toolbar-subtitle"> {translateText(locale, "in")} {location || translateText(locale, "Adama")}</span></div><div className="toolbar-actions"><button aria-expanded={filtersOpen} className="toolbar-chip mobile-filter" onClick={() => setFiltersOpen(!filtersOpen)} type="button"><SlidersHorizontal size={14} /> {translateText(locale, "Filters")}</button><label className="toolbar-chip"><ArrowDownWideNarrow size={14} /><span className="sr-only">{translateText(locale, "Sort results")}</span><select aria-label={translateText(locale, "Sort results")} onChange={(event) => updateFilter(setSortBy, "sort", event.target.value as typeof sortBy)} value={sortBy}><option value="relevance">{translateText(locale, "Relevant")}</option><option value="rating">{translateText(locale, "Top rated")}</option><option value="price-low">{translateText(locale, "Price: low")}</option><option value="price-high">{translateText(locale, "Price: high")}</option><option value="newest">{translateText(locale, "Newest")}</option></select></label><button aria-label={translateText(locale, "Grid view")} aria-pressed={display === "grid"} className="toolbar-chip view-toggle" onClick={() => updateFilter(setDisplay, "view", "grid", "")} type="button"><Grid2X2 size={15} /></button><button aria-label={translateText(locale, "List view")} aria-pressed={display === "list"} className="toolbar-chip view-toggle" onClick={() => updateFilter(setDisplay, "view", "list")} type="button"><List size={16} /></button></div></div>{activeFilters.length > 0 && <div className="active-filter-row"><span>{translateText(locale, "Filters:")}</span>{activeFilters.map((filter) => <button className="active-filter" key={filter.label} onClick={() => clearActiveFilter(filter.key)} type="button">{filter.label}<X size={12} /></button>)}<button className="text-link" onClick={resetFilters} type="button">{translateText(locale, "Clear all")}</button></div>}{error ? <div className="empty-state" role="alert"><h2>{translateText(locale, "Search could not load")}</h2><p>{error.message}</p><button className="button button-outline button-small" onClick={() => mutate()} type="button">{translateText(locale, "Try again")}</button></div> : isLoading ? <div aria-live="polite" className="search-loading" role="status">{translateText(locale, "Loading local professionals…")}</div> : filtered.length ? <div className={display === "grid" ? "search-worker-results" : "search-worker-results worker-list-view"}><WorkerGrid items={filtered} savedIds={savedIds} onToggleSave={onToggleSave} locale={locale} /></div> : <div className="empty-state"><div className="empty-state-icon"><Search size={20} /></div><h2>{translateText(locale, "No professionals match just yet")}</h2><p>{translateText(locale, "Try another skill or neighborhood, or clear your filters to see more people.")}</p><button className="button button-outline button-small" onClick={resetFilters} type="button">{translateText(locale, "Clear filters")}</button></div>}{totalPages > 1 && <div aria-label={translateText(locale, "Search result pages")} className="pagination"><button className="button button-outline button-small" disabled={currentPage <= 1} onClick={() => setCurrentPage((page) => page - 1)} type="button">{translateText(locale, "Previous")}</button><span>{translateText(locale, "Page")} {currentPage} {translateText(locale, "of")} {totalPages}</span><button className="button button-outline button-small" disabled={currentPage >= totalPages} onClick={() => setCurrentPage((page) => page + 1)} type="button">{translateText(locale, "Next")}</button></div>}<p className="demo-data-note">{translateText(locale, "Showing demo profiles for Adama. Ratings and availability are illustrative.")}</p></section></div><p className="sr-only" aria-live="polite">{total}  {translateText(locale, "professionals found.")}</p></div></main>
}

export function JobsPage({ jobs: availableJobs, locale, appliedJobIds, onApplyJob }: { jobs: Job[]; locale: Locale; appliedJobIds: string[]; onApplyJob: (job: Job) => void }) {
  const [query, setQuery] = useState("")
  const [jobType, setJobType] = useState("")
  const [location, setLocation] = useState("")
  const filtered = availableJobs.filter((job) => (!query || [job.title, job.company, job.category].some((item) => item.toLowerCase().includes(query.toLowerCase()))) && (!jobType || job.type === jobType) && (!location || job.location.toLowerCase().includes(location.toLowerCase())))
  const apply = (job: Job) => onApplyJob(job)
  return <main className="page-wrap"><div className="page-content"><PageIntro eyebrow="Good work is out there" title={translateText(locale, "Find your next opportunity.")} description="Browse local jobs from Adama employers, then explore what feels right for you." action={<Link className="button button-primary" href="/business/vacancies">{translateText(locale, "Post a job")} <ArrowRight size={15} /></Link>} /><div className="job-filters"><label className="job-search-input"><Search size={17} /><span className="sr-only">{translateText(locale, "Search jobs")}</span><input onChange={(event) => setQuery(event.target.value)} placeholder={translateText(locale, "Role, skill, or employer")} value={query} /></label><label className="field"><span className="sr-only">{translateText(locale, "Filter by job type")}</span><select onChange={(event) => setJobType(event.target.value)} value={jobType}><option value="">{translateText(locale, "All job types")}</option>{[...new Set(availableJobs.map((job) => job.type))].map((item) => <option key={item}>{item}</option>)}</select></label><label className="field"><span className="sr-only">{translateText(locale, "Filter by neighborhood")}</span><select onChange={(event) => setLocation(event.target.value)} value={location}><option value="">{translateText(locale, "All Adama")}</option>{neighborhoods.map((item) => <option key={item} value={item}>{item}</option>)}</select></label></div><div className="jobs-result-count"><strong>{filtered.length}  {translateText(locale, "open roles")}</strong><span>{translateText(locale, "· Updated locally")}</span></div>{filtered.length ? <JobList appliedIds={appliedJobIds} jobs={filtered} onApply={apply} /> : <div className="empty-state"><div className="empty-state-icon"><BriefcaseBusiness size={20} /></div><h2>{translateText(locale, "No jobs match these filters")}</h2><p>{translateText(locale, "Try another search or choose a different employment type.")}</p><button className="button button-outline button-small" onClick={() => { setQuery(""); setJobType(""); setLocation("") }} type="button">{translateText(locale, "Reset search")}</button></div>}<p className="demo-data-note">{translateText(locale, "Demo jobs for Adama. Applying here won't send your information to an employer.")}</p></div></main>
}

export function WorkerProfilePage({ worker, locale, savedIds, onToggleSave, onBook, onMessage, onReport }: { worker: Worker; locale: Locale; savedIds: string[]; onToggleSave: (id: string) => void; onBook: () => void; onMessage: () => void; onReport: () => void }) {
  return <main className="page-wrap"><div className="page-content"><div className="breadcrumb"><Link href="/">{translateText(locale, "Home")}</Link><ChevronRight size={13} /><Link href="/search">{translateText(locale, "Find workers")}</Link><ChevronRight size={13} /><span>{worker.name}</span></div><div className="detail-grid"><div><section className="detail-card profile-intro-card"><div className="profile-main"><WorkerAvatar className="profile-avatar" initials={worker.initials} photo={worker.id === "abebe-tadesse"} /><div><div className="profile-name-row"><h1>{worker.name}</h1>{worker.verified && <span className="status-pill"><BadgeCheck size={13} />  {translateText(locale, "Verified")}</span>}</div><p>{worker.headline}</p><div className="profile-meta-row"><span className="rating"><Star size={13} /> {worker.rating} <span>({worker.reviewCount}  {translateText(locale, "reviews)")}</span></span><span><MapPin size={14} /> {worker.location}</span><span><Clock3 size={14} /> {worker.experience}  {translateText(locale, "years")}</span></div></div></div><div className="pill-row">{worker.skills.map((skill) => <span className="pill" key={skill}>{skill}</span>)}</div></section><section className="detail-card"><h2>{translateText(locale, "A little about my work")}</h2><p>{worker.about}</p><h3>{translateText(locale, "What I can help with")}</h3><div className="pill-row">{worker.skills.map((skill) => <span className="pill" key={skill}>{skill}</span>)}</div></section><section className="detail-card"><h2>{translateText(locale, "Portfolio & recent work")}</h2><div className="portfolio-list">{workerPortfolio.filter((item) => item.workerId === worker.id).map((item) => <article className="portfolio-item" key={item.title}><span className="portfolio-mark"><Wrench size={16} /></span><div><strong>{item.title}</strong><span>{item.category} · {item.neighborhood}{translateText(locale, ", Adama")}</span><p>{item.summary}</p></div></article>)}{workerPortfolio.every((item) => item.workerId !== worker.id) && <p>{translateText(locale, "This professional is building a portfolio. Contact them to discuss related experience.")}</p>}</div><h3>{translateText(locale, "Credentials & checks")}</h3><div className="credential-list">{workerCredentials.filter((item) => item.workerId === worker.id).map((item) => <div className="credential-item" key={item.name}><ShieldCheck size={16} /><span><strong>{item.name}</strong><small>{item.issuer} · {item.year} · {item.status}</small></span></div>)}{workerCredentials.every((item) => item.workerId !== worker.id) && <p>{translateText(locale, "No credentials have been added to this demo profile.")}</p>}</div></section><section className="detail-card"><h2>{translateText(locale, "Recent reviews")}</h2><div className="review-card"><span className="review-initial">MT</span><div><strong>“{worker.name.split(" ")[0]}  {translateText(locale, "made the whole process easy.”")}</strong><p>{translateText(locale, "Great communication, arrived on time, and did careful work. I would happily recommend them to a neighbor.")}</p><span className="rating"><Star size={12} /> 5.0 <span>{translateText(locale, "· Nov 2026 · Demo review")}</span></span></div></div><div className="review-card"><span className="review-initial warm">AG</span><div><strong>{translateText(locale, "“A really thoughtful local professional.”")}</strong><p>{translateText(locale, "We talked through the details before booking and everything went just as planned.")}</p><span className="rating"><Star size={12} /> 4.8 <span>{translateText(locale, "· Oct 2026 · Demo review")}</span></span></div></div></section><section className="detail-card"><h2>{translateText(locale, "Languages & experience")}</h2><div className="profile-info-grid"><div><span>{translateText(locale, "Languages")}</span><strong>{worker.languages.join(", ")}</strong></div><div><span>{translateText(locale, "Experience")}</span><strong>{worker.experience}  {translateText(locale, "years in")} {worker.category.toLowerCase()}</strong></div><div><span>{translateText(locale, "Home area")}</span><strong>{worker.location}</strong></div></div></section></div><aside className="detail-sidebar"><div className="detail-card booking-card"><span className="status-pill gold">{worker.available ? "Available for new work" : "Limited availability"}</span><div className="detail-price">{formatETB(worker.hourlyRate)} <small>{translateText(locale, "/ hour")}</small></div><p>{translateText(locale, "Let's talk about what you need and find a time that works.")}</p><ul className="detail-list"><li><ShieldCheck size={16} />  {translateText(locale, "Profile details reviewed")}</li><li><MessageCircle size={16} />  {translateText(locale, "Agree on details together")}</li><li><MapPin size={16} /> {worker.location}</li></ul><button className="button button-primary full-width" onClick={onBook} type="button">{translateText(locale, "Request a service")} <ArrowRight size={15} /></button><button aria-pressed={savedIds.includes(worker.id)} className="button button-outline full-width" onClick={() => onToggleSave(worker.id)} type="button"><Heart fill={savedIds.includes(worker.id) ? "currentColor" : "none"} size={15} />{savedIds.includes(worker.id) ? "Saved to your list" : "Save this professional"}</button><button className="button button-outline full-width" onClick={onMessage} type="button"><MessageCircle size={15} />  {translateText(locale, "Message this professional")}</button><p className="small-demo-note">{translateText(locale, "Demo request only. No real booking or payment is made.")}</p></div><div className="detail-card"><h2>{translateText(locale, "Good to know")}</h2><p>{translateText(locale, "Keep personal details private until you're comfortable. Discuss the work, schedule, and price before confirming.")}</p><Link className="text-link" href="/help">{translateText(locale, "Read safety tips")} <ArrowRight size={14} /></Link><button className="text-link report-link" onClick={onReport} type="button">{translateText(locale, "Report this profile")}</button></div></aside></div></div></main>
}

export function JobDetailPage({ job, locale, isApplied, onApply, onToast }: { job: Job; locale: Locale; isApplied: boolean; onApply: () => void; onToast: (message: string) => void }) {
  const [savedJobIds, setSavedJobIds] = useDemoStorageState<string[]>("carava-demo-saved-jobs", [])
  const isSaved = savedJobIds.includes(job.id)
  const toggleSaved = () => { const next = isSaved ? savedJobIds.filter((id) => id !== job.id) : [...savedJobIds, job.id]; setSavedJobIds(next); onToast(next.includes(job.id) ? "Job saved to this browser." : "Job removed from saved jobs.") }
  return <main className="page-wrap"><div className="page-content"><div className="breadcrumb"><Link href="/jobs">{translateText(locale, "Jobs")}</Link><ChevronRight size={13} /><span>{job.title}</span></div><div className="detail-grid"><div><section className="detail-card job-detail-title"><div className="job-logo">{job.company.charAt(0)}</div><div><span className="status-pill">{job.verified ? <><BadgeCheck size={12} />  {translateText(locale, "Verified employer")}</> : "Local employer"}</span><h1>{job.title}</h1><div className="job-meta"><span><BriefcaseBusiness size={13} /> {job.company}</span><span><MapPin size={13} /> {job.location}</span><span><Clock3 size={13} /> {job.posted}</span></div></div></section><section className="detail-card"><h2>{translateText(locale, "About this opportunity")}</h2><p>{job.description}</p><h3>{translateText(locale, "What you'll bring")}</h3><ul className="check-list"><li><Check size={15} />  {translateText(locale, "Experience with")} {job.category.toLowerCase()}</li><li><Check size={15} />  {translateText(locale, "Reliable communication and punctuality")}</li><li><Check size={15} />  {translateText(locale, "Relevant skills for the role")}</li></ul><h3>{translateText(locale, "Schedule & details")}</h3><p>{job.type}  {translateText(locale, "position ·")} {job.salary}  {translateText(locale, "· Start date to be discussed with the employer. Applications are handled as demo-only in this prototype.")}</p><h3>{translateText(locale, "About the employer")}</h3><p>{job.company}  {translateText(locale, "is a local Adama organization looking to meet skilled, dependable people in the community.")}</p></section></div><aside className="detail-sidebar"><div className="detail-card"><span className="job-tag">{job.type}</span><div className="detail-price">{job.salary}</div><ul className="detail-list"><li><MapPin size={16} /> {job.location}</li><li><Users size={16} /> {job.applicants}  {translateText(locale, "demo applicants")}</li><li><Clock3 size={16} />  {translateText(locale, "Posted")} {job.posted}</li></ul><button aria-pressed={isApplied} className="button button-primary full-width" disabled={isApplied} onClick={onApply} type="button">{isApplied ? "Application sent" : "Apply for this job"} <ArrowRight size={15} /></button><button aria-pressed={isSaved} className="button button-outline full-width" onClick={toggleSaved} type="button"><Heart fill={isSaved ? "currentColor" : "none"} size={15} /> {isSaved ? "Saved job" : "Save this job"}</button><p className="small-demo-note">{translateText(locale, "Demo only — this does not send an application.")}</p></div></aside></div></div></main>
}

export function ServiceDetailPage({ serviceId, locale, onBook }: { serviceId: string; locale: Locale; onBook: (service: MarketplaceService) => void }) {
  const service = services.find((item) => item.id === serviceId) ?? services[0]
  const worker = workers.find((item) => item.id === service.providerId) ?? workers[0]
  return <main className="page-wrap"><div className="page-content"><div className="breadcrumb"><Link href="/categories">{translateText(locale, "Services")}</Link><ChevronRight size={13} /><span>{service.title}</span></div><div className="detail-grid"><div><section className="detail-card"><div className="service-banner"><Wrench size={27} /></div><span className="eyebrow">{service.category}</span><h1 className="service-title">{service.title}</h1><p>{worker.about}</p><div className="pill-row"><span className="pill">{translateText(locale, "Clear pricing")}</span><span className="pill">{translateText(locale, "Local professional")}</span><span className="pill">{translateText(locale, "Adama")}</span></div></section><section className="detail-card"><h2>{translateText(locale, "Meet your provider")}</h2><Link className="provider-row" href={`/workers/${worker.id}`}><WorkerAvatar initials={worker.initials} /><span><strong>{worker.name}</strong><small>{worker.headline}</small></span><ArrowRight size={16} /></Link><p>{translateText(locale, "Experienced, reviewed, and ready to discuss the details of your request.")}</p></section><section className="detail-card"><h2>{translateText(locale, "What to expect")}</h2><ul className="check-list"><li><Check size={15} />  {translateText(locale, "Share a few details about your project")}</li><li><Check size={15} />  {translateText(locale, "Agree on scope, timing, and final price")}</li><li><Check size={15} />  {translateText(locale, "Review the completed work")}</li></ul></section></div><aside className="detail-sidebar"><div className="detail-card"><span className="rating"><Star size={13} /> {service.rating} <span>· {worker.reviewCount}  {translateText(locale, "reviews")}</span></span><div className="detail-price">{formatETB(service.price)} <small>/ {service.unit}</small></div><p>{translateText(locale, "Tell us what you need and this professional can follow up in the demo workspace.")}</p><button className="button button-primary full-width" onClick={() => onBook(service)} type="button">{translateText(locale, "Request this service")} <ArrowRight size={15} /></button><Link className="button button-outline full-width" href={`/workers/${worker.id}`}>{translateText(locale, "View full profile")}</Link><p className="small-demo-note">{translateText(locale, "Demo request only — no payment is collected.")}</p></div></aside></div></div></main>
}

const infoContent: Record<string, { eyebrow: string; title: string; intro: string; sections: [string, string][] }> = {
  about: { eyebrow: "A better way to find good work", title: "Opportunity starts in our own community.", intro: "Carava is an early-stage marketplace built to bring local skills, services, and opportunities closer to the people who need them.", sections: [["Made for the way people work", "Whether you are looking for trusted help, sharing a skill, hiring a team, or finding your next job, Carava gives people one thoughtful place to start."], ["Starting in Adama", "We are beginning in Adama, with a focus on local neighborhoods, familiar languages, and the relationships that make good work possible."], ["A demo with a real direction", "This experience uses illustrative profiles and sample information. Booking, verification, payments, and messaging are not connected to live services yet."]] },
  help: { eyebrow: "Here when you need us", title: "A little help goes a long way.", intro: "Find practical guidance for using Carava and making good decisions when arranging local work.", sections: [["How do I contact a professional?", "Open a profile or service and choose Request. In this demo you can see the request flow, but no real message is sent."], ["How does profile verification work?", "Verification status on this demo is illustrative. A production service would review submitted information and communicate the result securely."], ["How should we agree on a price?", "Discuss the scope, materials, schedule, and total amount before work begins. The prices shown here are examples in Ethiopian Birr."], ["Need more help?", "Send a note from the contact page. The demo form will confirm your message locally without delivering it."]] },
  contact: { eyebrow: "We would love to hear from you", title: "Start a conversation.", intro: "Questions, ideas, or feedback about bringing Carava to your community? Send us a note.", sections: [["Local launch", "Carava is currently a frontend demo focused on Adama, Ethiopia."], ["Community feedback", "We are interested in hearing which categories, neighborhoods, languages, and safety features matter most to you."]] },
  privacy: { eyebrow: "Your information matters", title: "Privacy, with care.", intro: "This demo does not connect to a backend and does not transmit account, booking, or message information.", sections: [["Demo data", "Illustrative sample profiles and records are stored in the frontend code. Preferences such as saved professionals may be kept in this browser only."], ["Private details", "Public profile examples do not show personal phone numbers, private email addresses, identity documents, or exact residential addresses."], ["Future production service", "Before launch, Carava would need published privacy practices covering collection, use, retention, and your choices. This page is an informational placeholder, not legal advice."]] },
  terms: { eyebrow: "Clear expectations", title: "Using Carava.", intro: "These demo terms describe the experience, not a binding production agreement.", sections: [["A marketplace demo", "Listings, ratings, fees, messages, verification statuses, and financial summaries are illustrative. They do not represent a real offer or transaction."], ["Good-faith conversations", "In a future live marketplace, users would be expected to provide accurate information, respect one another, and agree on work details before starting."], ["Before launch", "Final terms, dispute rules, payment arrangements, and eligibility requirements must be reviewed and published before the platform handles live activity."]] },
}

export function InfoPage({ page, locale, onSend }: { page: string; locale: Locale; onSend: (name: string, email: string, body: string) => void }) {
  const content = infoContent[page] ?? infoContent.about
  const [sent, setSent] = useState(false)
  const [name, setName] = useState("")
  const [email, setEmail] = useState("")
  const [message, setMessage] = useState("")
  return <main className="page-wrap"><div className="page-content info-page"><PageIntro eyebrow={translateText(locale, content.eyebrow)} title={translateText(locale, content.title)} description={translateText(locale, content.intro)} />{page === "contact" && <section className="detail-card contact-form-card"><h2>{translateText(locale, "Send a note")}</h2>{sent ? <div className="inline-success"><Check size={17} /> {translateText(locale, "Your demo message is ready. It has not been sent to a live support team.")}</div> : <form className="contact-form" onSubmit={(event) => { event.preventDefault(); onSend(name, email, message); setSent(true) }}><label className="field"><span>{translateText(locale, "Your name")}</span><input autoComplete="name" onChange={(event) => setName(event.target.value)} required value={name} /></label><label className="field"><span>{translateText(locale, "Email address")}</span><input autoComplete="email" onChange={(event) => setEmail(event.target.value)} required type="email" value={email} /></label><label className="field"><span>{translateText(locale, "What would you like to share?")}</span><textarea onChange={(event) => setMessage(event.target.value)} required value={message} /></label><button className="button button-primary" type="submit">{translateText(locale, "Send demo message")} <ArrowRight size={14} /></button></form>}</section>}<div className="info-content">{content.sections.map(([title, body]) => <section className="detail-card" key={title}><h2>{translateText(locale, title)}</h2><p>{translateText(locale, body)}</p></section>)}</div></div></main>
}

export function BookingDialog({ worker, service, locale = "am", onClose, onConfirm }: { worker: Worker | null; service?: MarketplaceService | null; locale?: Locale; onClose: () => void; onConfirm: (worker: Worker, date: string, schedule: string, details: string) => void }) {
  const [date, setDate] = useState("")
  const [schedule, setSchedule] = useState("")
  const [details, setDetails] = useState("")
  const targetKey = `${worker?.id ?? ""}|${service?.id ?? ""}`
  const [syncedTargetKey, setSyncedTargetKey] = useState(targetKey)
  if (syncedTargetKey !== targetKey) {
    setSyncedTargetKey(targetKey)
    setDate("")
    setSchedule("")
    setDetails("")
  }
  const dates = getScheduleOptions(new Date(), 7, locale)
  const dialogRef = useDialogFocus(Boolean(worker), onClose)
  if (!worker) return null
  return <div className="confirm-backdrop booking-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}><section aria-labelledby="booking-title" aria-modal="true" className="booking-dialog" ref={dialogRef} role="dialog" tabIndex={-1}><button aria-label={translateText(locale, "Close request")} className="dialog-close icon-button" onClick={onClose} type="button"><X size={17} /></button><div className="eyebrow">{translateText(locale, "A GOOD PLACE TO START")}</div><h2 id="booking-title">{service ? translateText(locale, "Request this service") : translateText(locale, "Request a service")}</h2><p>{translateText(locale, "Share a couple of details with")} {worker.name}{translateText(locale, ". You'll review the plan before anything is confirmed.")}</p><div className="booking-summary"><span className="worker-avatar">{worker.initials}</span><span><strong>{service ? service.title : worker.name}</strong><small>{service ? `${service.category} · ${formatETB(service.price)} / ${service.unit}` : `${worker.category} · ${formatETB(worker.hourlyRate, locale)} / hour`}</small></span></div><form className="auth-form" onSubmit={(event) => { event.preventDefault(); if (date && schedule && details.trim()) onConfirm(worker, date, schedule, details.trim()) }}><fieldset className="schedule-fieldset"><legend>{translateText(locale, "Choose a day")}</legend><div className="schedule-options">{dates.map((option) => <button aria-pressed={date === option.value} aria-label={option.label} className={`schedule-date ${date === option.value ? "selected" : ""}`} key={option.value} onClick={() => setDate(option.value)} type="button"><span>{option.weekday}</span><strong>{option.day}</strong></button>)}</div></fieldset><fieldset className="schedule-fieldset"><legend>{translateText(locale, "Choose a time")}</legend><div className="schedule-times">{scheduleTimes.map((time) => { const label = new Intl.DateTimeFormat(locale === "am" ? "am-ET" : locale === "om" ? "om-ET" : "en-ET", { hour: "numeric", minute: "2-digit" }).format(new Date(2020, 0, 1, Number(time.slice(0, 2)), Number(time.slice(3)))); return <button aria-pressed={schedule === time} className={`schedule-time ${schedule === time ? "selected" : ""}`} key={time} onClick={() => setSchedule(time)} type="button">{label}</button> })}</div></fieldset><label className="field"><span>{translateText(locale, "What do you need done?")}</span><textarea onChange={(event) => setDetails(event.target.value)} placeholder={translateText(locale, "A short description helps set clear expectations")} required value={details} /></label><div className="auth-note">{translateText(locale, "Demo only: no real booking, message, or payment will be sent. You can review this request in the customer dashboard.")}</div><button className="button button-primary" disabled={!date || !schedule || !details.trim()} type="submit">{translateText(locale, "Review demo request")} <ArrowRight size={15} /></button></form></section></div>
}
